  button(body,"Tela cheia",CARD,()->fullscreen(frame,v,controls));if(index+1<eps.length())button(body,"Próximo episódio  →",RED,()->play(s,eps,index+1,origin));button(body,"Todos os episódios",CARD,()->details(s,origin));handler.postDelayed(progress,5000);
