 void fullscreen(FrameLayout frame,VideoView v,MediaController controls){
  ViewGroup parent=(ViewGroup)frame.getParent();int index=parent.indexOfChild(frame);ViewGroup.LayoutParams original=frame.getLayoutParams();int position=v.getCurrentPosition();boolean wasPlaying=v.isPlaying();parent.removeView(frame);
  Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar_Fullscreen);FrameLayout full=new FrameLayout(this);full.setBackgroundColor(Color.BLACK);full.addView(frame,new FrameLayout.LayoutParams(-1,-1));TextView close=label("‹  Voltar",16,WHITE);close.setPadding(dp(16),dp(16),dp(16),dp(16));close.setBackground(bg(0xaa090d14,8));full.addView(close,new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.LEFT));dialog.setContentView(full);dialog.getWindow().setLayout(-1,-1);close.setOnClickListener(x->dialog.dismiss());dialog.setOnDismissListener(d->{int exitPosition=v.getCurrentPosition();boolean resume=v.isPlaying();full.removeView(frame);parent.addView(frame,index,original);controls.setAnchorView(v);v.seekTo(exitPosition);if(resume)v.start();});dialog.show();dialog.getWindow().setLayout(-1,-1);controls.setAnchorView(v);v.seekTo(position);if(wasPlaying)v.start();
 }
