 class CinemaArt extends View{Paint p=new Paint(3);CinemaArt(){super(MainActivity.this);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));for(int i=0;i<6;i++){p.setColor(0x22e9769b);c.save();c.rotate(-20,w*.85f,h*.5f);c.drawRoundRect(w*.68f+i*dp(12),-dp(60),w*1.2f+i*dp(12),h+dp(40),dp(16),dp(16),p);c.restore();}p.setStyle(Paint.Style.FILL);p.setColor(0x22f20d46);c.drawCircle(w*.9f,h*.2f,dp(60),p);}}
 class Icon extends View{String type;int color;Paint p=new Paint(3);Icon(String t,int c){super(MainActivity.this);type=t;color=c;}protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.scale(getWidth()/24f,getHeight()/24f);p.setColor(color);p.setStrokeWidth(1.7f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setStyle(Paint.Style.STROKE);Path a=new Path();switch(type){case "home":a.moveTo(3,11);a.lineTo(12,3);a.lineTo(21,11);a.moveTo(5,10);a.lineTo(5,21);a.lineTo(10,21);a.lineTo(10,15);a.lineTo(14,15);a.lineTo(14,21);a.lineTo(19,21);a.lineTo(19,10);break;case "search":canvas.drawCircle(10,10,6,p);canvas.drawLine(15,15,21,21,p);break;case "heart":a.moveTo(12,21);a.cubicTo(-6,10,5,-1,12,7);a.cubicTo(19,-1,30,10,12,21);break;case "user":canvas.drawCircle(12,7,4,p);a.moveTo(4,22);a.lineTo(4,19);a.cubicTo(4,11,20,11,20,19);a.lineTo(20,22);break;case "play":a.moveTo(8,4);a.lineTo(20,12);a.lineTo(8,20);a.close();p.setStyle(Paint.Style.FILL);break;case "back":a.moveTo(15,5);a.lineTo(8,12);a.lineTo(15,19);break;case "shield":a.moveTo(12,2);a.lineTo(21,6);a.lineTo(19,16);a.lineTo(12,22);a.lineTo(5,16);a.lineTo(3,6);a.close();a.moveTo(8,12);a.lineTo(11,15);a.lineTo(16,9);break;case "settings":canvas.drawCircle(12,12,4,p);canvas.drawCircle(12,12,9,p);for(int i=0;i<8;i++){canvas.save();canvas.rotate(i*45,12,12);canvas.drawLine(12,1,12,4,p);canvas.restore();}break;default:canvas.drawRoundRect(2,4,22,20,2,2,p);canvas.drawLine(6,4,6,20,p);canvas.drawLine(18,4,18,20,p);for(int y=8;y<20;y+=4){canvas.drawLine(2,y,6,y,p);canvas.drawLine(18,y,22,y,p);}}canvas.drawPath(a,p);canvas.restore();}}
